CREATE TABLE departments (
  dept_id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name    text NOT NULL UNIQUE
);

-- 1:N  the FK sits on the many side
CREATE TABLE courses (
  code    text PRIMARY KEY,
  title   text NOT NULL,
  dept_id int  NOT NULL REFERENCES departments (dept_id)
);

CREATE TABLE students (
  student_id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL UNIQUE
);

-- 1:1  the FK is also the PK, so at most one profile per student
CREATE TABLE student_profiles (
  student_id int PRIMARY KEY REFERENCES students (student_id) ON DELETE CASCADE,
  bio        text
);

-- M:N  a junction table with a composite PK
CREATE TABLE enrolments (
  student_id  int  REFERENCES students (student_id),
  course_code text REFERENCES courses (code),
  grade       int,
  PRIMARY KEY (student_id, course_code)
);

CREATE TABLE countries (
  iso2 char(2) PRIMARY KEY,          -- natural: short, stable, already unique
  name text NOT NULL
);

CREATE TABLE customers (
  customer_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,  -- surrogate
  email       text NOT NULL UNIQUE,  -- natural candidate, but it can change
  country     char(2) NOT NULL REFERENCES countries (iso2)
);

