INSERT INTO customers (customer_id, email, country) VALUES (7, 'x@shop.io', 'PT');
-- ERROR: cannot insert a non-DEFAULT value into column "customer_id"

CREATE TABLE lecturers (lecturer_id int PRIMARY KEY, name text NOT NULL);

CREATE TABLE courses (
  code    text PRIMARY KEY,
  lead_id int REFERENCES lecturers ON DELETE SET NULL   -- optional link
);

CREATE TABLE enrolments (
  student_id  int  NOT NULL REFERENCES students ON DELETE CASCADE,  -- owned rows
  course_code text NOT NULL REFERENCES courses  ON DELETE RESTRICT, -- keep history
  PRIMARY KEY (student_id, course_code)
);

DELETE FROM courses WHERE code = 'DB101';
-- ERROR: update or delete on table "courses" violates RESTRICT setting of foreign key constraint ...

-- Racy: two requests can both pass the SELECT
SELECT 1 FROM users WHERE email = 'ana@shop.io';
INSERT INTO users (email) VALUES ('ana@shop.io');

-- Safe: the constraint decides; handle the conflict explicitly
ALTER TABLE users ADD CONSTRAINT users_email_key UNIQUE (email);
INSERT INTO users (email) VALUES ('ana@shop.io')
ON CONFLICT (email) DO NOTHING
RETURNING user_id;   -- no row back means it already existed

ALTER TABLE users ADD COLUMN deleted_at timestamptz;

-- Soft delete:
UPDATE users SET deleted_at = now() WHERE user_id = 42;

-- Every read now needs the filter:
SELECT user_id, email FROM users WHERE deleted_at IS NULL;

-- Deliberate denormalisation: the invoice freezes what was true then
CREATE TABLE invoices (
  invoice_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id   bigint NOT NULL REFERENCES customers,
  billing_name  text NOT NULL,      -- copied on purpose, never updated
  total         numeric(12,2) NOT NULL
);

