CREATE TABLE venues (
  venue_id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name     text NOT NULL UNIQUE,
  seats    int  NOT NULL CHECK (seats > 0)
);

CREATE TABLE events (
  event_id  int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  venue_id  int NOT NULL REFERENCES venues ON DELETE RESTRICT,  -- keep history
  title     text NOT NULL,
  starts_at timestamptz NOT NULL,
  ends_at   timestamptz NOT NULL,
  CONSTRAINT ends_after_start CHECK (ends_at > starts_at)
);

CREATE TABLE tickets (
  event_id   int  NOT NULL REFERENCES events ON DELETE CASCADE,
  seat       text NOT NULL,
  price      numeric(10,2) NOT NULL CHECK (price >= 0),
  holder     text,                                   -- NULL until sold
  PRIMARY KEY (event_id, seat)                       -- a seat sells once per event
);

