CREATE TEMP TABLE probe_result (step int, probe text, outcome text);
DO $$
DECLARE p record; v text;
BEGIN
  FOR p IN SELECT * FROM lab_probe ORDER BY step LOOP
    BEGIN
      IF upper(left(p.stmt, 6)) = 'SELECT' THEN EXECUTE p.stmt INTO v;
      ELSE EXECUTE p.stmt; v := 'ok';
      END IF;
    EXCEPTION
      WHEN unique_violation THEN v := 'unique_violation';
      WHEN foreign_key_violation OR restrict_violation THEN v := 'foreign_key_violation';
      WHEN check_violation THEN v := 'check_violation';
      WHEN not_null_violation THEN v := 'not_null_violation';
      WHEN generated_always THEN v := 'generated_always';
      WHEN OTHERS THEN v := 'error: ' || SQLERRM;
    END;
    INSERT INTO probe_result VALUES (p.step, p.probe, v);
  END LOOP;
END $$;
SELECT step, probe, outcome FROM probe_result

