CREATE TEMP TABLE rule_result (rule text, outcome text);
DO $$ BEGIN
  BEGIN
    INSERT INTO customers (email, name) SELECT email, 'Copy' FROM customers LIMIT 1;
    INSERT INTO rule_result VALUES ('duplicate email', 'accepted');
  EXCEPTION WHEN unique_violation THEN INSERT INTO rule_result VALUES ('duplicate email', 'rejected');
  END;
  BEGIN
    INSERT INTO order_lines (order_id, sku, qty, unit_price) SELECT order_id, 'NO-SUCH-SKU', 1, 1.00 FROM orders LIMIT 1;
    INSERT INTO rule_result VALUES ('unknown sku', 'accepted');
  EXCEPTION WHEN foreign_key_violation THEN INSERT INTO rule_result VALUES ('unknown sku', 'rejected');
  END;
  BEGIN
    UPDATE order_lines SET qty = 0 WHERE ctid = (SELECT ctid FROM order_lines LIMIT 1);
    INSERT INTO rule_result VALUES ('zero qty', 'accepted');
  EXCEPTION WHEN check_violation THEN INSERT INTO rule_result VALUES ('zero qty', 'rejected');
  END;
END $$;
SELECT 'customer' AS kind, c.email AS key, c.name, count(DISTINCT o.order_id)::int AS n,
       coalesce(sum(l.qty * l.unit_price), 0) AS amount
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.customer_id
LEFT JOIN order_lines l ON l.order_id = o.order_id
GROUP BY c.customer_id, c.email, c.name
UNION ALL
SELECT 'product', p.sku, p.name, count(l.order_id)::int, coalesce(sum(l.qty), 0)
FROM products p
LEFT JOIN order_lines l ON l.sku = p.sku
GROUP BY p.sku, p.name
UNION ALL
SELECT 'rule', rule, outcome, NULL, NULL FROM rule_result

